{
  "spec": "This plan adds CSV and Markdown output formats to the exporter tool, ensuring they handle missing keys by writing empty cells. It introduces a `--fields` CLI argument to allow users to select and order specific columns for any format. The new formats are registered in the existing registry pattern and included in the `--list-formats` output. Existing JSON and text modules remain untouched to preserve byte-for-byte compatibility. All new functionality is covered by tests written before implementation.",
  "stack": "Python, csv, markdown, pytest",
  "tasks": [
    {
      "id": 1,
      "title": "Implement CSV writer with header and quoting logic",
      "files": [
        "exporter/formats/csv_fmt.py"
      ],
      "test": "tests/test_csv.py checks that output matches Python's csv module behavior for quoted values and empty cells for missing keys."
    },
    {
      "id": 2,
      "title": "Implement Markdown table writer with pipe escaping",
      "files": [
        "exporter/formats/markdown_fmt.py"
      ],
      "test": "tests/test_markdown.py checks that `|` is escaped as `\\|` and missing keys result in empty cells."
    },
    {
      "id": 3,
      "title": "Register new formats in the format registry",
      "files": [
        "exporter/formats/__init__.py"
      ],
      "test": "tests/test_registry.py checks that 'csv' and 'markdown' are available in `formats.names()`."
    },
    {
      "id": 4,
      "title": "Add file extensions for new formats to settings",
      "files": [
        "exporter/settings.py"
      ],
      "test": "tests/test_settings.py checks that `EXTENSIONS` contains correct mappings for csv and markdown."
    },
    {
      "id": 5,
      "title": "Add --fields argument to CLI and update format invocation",
      "files": [
        "exporter/cli.py"
      ],
      "test": "tests/test_cli.py checks that `--fields a,b` correctly filters and orders columns in CSV output."
    },
    {
      "id": 6,
      "title": "Ensure default output goes to stdout when no path is given",
      "files": [
        "exporter/cli.py"
      ],
      "test": "tests/test_cli.py checks that output is written to stdout when no path is provided."
    },
    {
      "id": 7,
      "title": "Update --list-formats to include new formats",
      "files": [
        "exporter/cli.py"
      ],
      "test": "tests/test_cli.py checks that `--list-formats` output includes 'csv' and 'markdown'."
    }
  ]
}

